                        this->fire.pos[0] = 10.0f * x;
                        this->fire.pos[1] = 10.0f * y;
                        this->fire.pos[2] = 10.0f * z;
                        this->fire.pos[3] = 1.0f;
                        this->fire.DrawRaster();
                    }
                }
            }
        }
    }
}

